SELECT
  m.id, COALESCE((SELECT id FROM product_types WHERE name = 'バイオスティミュラント' LIMIT 1), (SELECT id FROM product_types WHERE name = 'BS資材' LIMIT 1)), 'Actibio X EVO53',
