-- products row 4: BIOZ Diamond / maker=ICL JAPAN
INSERT INTO products (
  maker_id, product_type_id, name, product_name_jp, general_purpose,
  primary_compound, mode_of_action, commercial_status,
  technology_action, disease_pest_info, expected_effects_official,
  expected_effects_farmille, usage_summary, precautions,
  storage_shelf_life, notes, confidence, is_public,
  fertilizer_registered, pesticide_registered
)
SELECT
  m.id, COALESCE((SELECT id FROM product_types WHERE name = 'バイオスティミュラント' LIMIT 1), (SELECT id FROM product_types WHERE name = 'BS資材' LIMIT 1)), 'BIOZ Diamond',
  'ダイヤモンド', '土壌と植物の相互作用を強化し、土壌水分と養分利用効率、根の発達、土壌微生物叢の活性化を促す',
  '複数の有機物、窒素、カリウム、全有機炭素', '微生物の多様性と活性を高め、根の発達を直接刺激することで、微生物との結びつきが強まった根系が養分の取り込みと吸収効率を高める', '公式ページ掲載',
  '複数の有機物をベースに、土壌と植物の相互作用を強化し、微生物の多様性と活性を高め、根の発達を直接刺激する', '明記なし', '複数の有機物をベースにしたバイオスティミュラントで、土壌と植物の相互作用を強化します。微生物の多様性と活性を高め、根の発達を直接刺激することで、微生物との結びつきが強まった根系は、養分の取り込みと吸収効率を高めます。土壌水分と養分利用効率を高める、植物の発育を促す生物刺激、土壌微生物叢を活性化し、土壌改良を促進する、土壌の化学的、物理的、生物学的特性のバランスを保たせる、生物活性物質を高濃度に配合',
  '土壌水分を使いやすくする、肥料を効きやすくする、根張りを助ける、土壌微生物を活性化する、土づくりを助ける、生育を促す', '推奨施用量は希釈倍率基準ではなく単位面積あたりの投下量が基準。耕起前、播種直後、植え付け前、植溝内散布、生育期間中など作物別に施用する。', '残留性の除草剤、土壌処理剤と混用可能。農薬と初めてタンク内で混合する前にボトルテストを行うことを推奨。出芽初期の除草剤と混用される際は弊社技術者に相談。ラベルに記載された作物にのみ使用。使用前に小規模な試験を推奨。',
  '製造年月日より3年', '公式PDFの製品特性では原産国ブラジル、製品荷姿5L/本、物理的性質は暗褐色非粘稠懸濁液、用途は土壌散布、製品コード501013。Webページでは作物別に詳細施用量が掲載され、PDFでは栽培品目がダイズ・トウモロコシ・小麦・大麦に限定的に記載されているため、Webページを優先しつつ差分を要確認。', '高', true,
  NULL, NULL
FROM (SELECT u.id FROM users u JOIN maker_profiles mp ON mp.user_id = u.id WHERE u.role = 'maker' AND u.status = 'active' AND mp.company_name = 'ICL JAPAN' LIMIT 1) AS m
ON CONFLICT (name, maker_id) DO UPDATE SET
  product_type_id           = EXCLUDED.product_type_id,
  product_name_jp           = EXCLUDED.product_name_jp,
  general_purpose           = EXCLUDED.general_purpose,
  primary_compound          = EXCLUDED.primary_compound,
