  disease_pest_info         = EXCLUDED.disease_pest_info,
  expected_effects_official = EXCLUDED.expected_effects_official,
  expected_effects_farmille = EXCLUDED.expected_effects_farmille,
  usage_summary             = EXCLUDED.usage_summary,
  precautions               = EXCLUDED.precautions,
  storage_shelf_life        = EXCLUDED.storage_shelf_life,
  notes                     = EXCLUDED.notes,
  confidence                = EXCLUDED.confidence,
  is_public                 = EXCLUDED.is_public,
  fertilizer_registered     = EXCLUDED.fertilizer_registered,
  pesticide_registered      = EXCLUDED.pesticide_registered,
  updated_at                = now();

