-- products row 5: BIOZ Moonstone / maker=ICL JAPAN
INSERT INTO products (
  maker_id, product_type_id, name, product_name_jp, general_purpose,
  primary_compound, mode_of_action, commercial_status,
  technology_action, disease_pest_info, expected_effects_official,
  expected_effects_farmille, usage_summary, precautions,
  storage_shelf_life, notes, confidence, is_public,
  fertilizer_registered, pesticide_registered
)
SELECT
  m.id, COALESCE((SELECT id FROM product_types WHERE name = 'バイオスティミュラント' LIMIT 1), (SELECT id FROM product_types WHERE name = 'BS資材' LIMIT 1)), 'BIOZ Moonstone',
  'ムーンストーン', '非生物的ストレスからの回復を早め、作物の新陳代謝、栄養吸収、転流、着花・着果を支援する',
  '17種類の必須アミノ酸、9種類の栄養素、窒素、リン酸、カリウム、硫黄、ホウ素、銅、マンガン、モリブデン、亜鉛、有機体炭素、グルタミン酸 分析例20,000ppm、アスパラギン酸 分析例4,000ppm、保証成分 6-1-1、0.1MnO、0.1B2O3', '17種類の必須アミノ酸と9種類の栄養素による葉面からの補給により、作物の新陳代謝、栄養吸収、転流、非生物的ストレス後の回復を支援する', '公式ページ掲載',
  'アミノ酸及び微量要素の働きにより、非生物的ストレスからの回復を早め、作物体内の栄養吸収と転流速度を向上させる', '明記なし', 'ムーンストーンは、作物全般が対象の葉面散布肥料で、17種類の必須アミノ酸に加え、9種類の栄養素を配合しています。グルタミン酸（分析例として20,000 ppm）とアスパラギン酸（分析例として4,000 ppm）を豊富に含み、速やかに植物の反応が見えます。アミノ酸及び微量要素の働きにより、非生物的ストレス（高温、低温、風水害、ひょうによる葉の損傷、農薬による葉焼け）からの回復を早めます。水稲・小麦・トウモロコシ・馬鈴薯など多岐にわたる作物の高収量を実現します。作物の新陳代謝を促進、作物体内の栄養吸収と転流速度を向上、夏場の高温からの回復促進、農薬による葉の薬害低減、花や果実の着実性を向上',
  '暑さ・寒さ・風水害・ひょう・薬害後の回復を助ける、葉から栄養を補う、作物の代謝を助ける、栄養の移動を助ける、花や果実のつきを助ける', '推奨施用量は希釈倍率基準ではなく単位面積あたりの投下量100～200ml/10aが基準。ムーンストーン希釈液単独または農薬資材との混合希釈液をブームスプレイヤーにて葉面散布する。', 'タンク投入前にボトルをよく振って使用。単独葉面散布の場合は少量散布6L~/10aが可能で、展着剤の使用を推奨。農薬資材との混合希釈液を葉面散布する場合、希釈倍率は混用する農薬資材に合わせる。農薬等と初めてタンク内で混合する前にボトルテストを行い、適合性を確認。石灰硫黄合剤、銅剤との混用を避ける。使用前に小規模な試験を推奨。',
  '製造年月日より3年', '公式PDFの製品特性では物理的性質は褐色非粘稠分離液、用途は葉面散布、製品荷姿5L/本、原産国ブラジル、製品コード500960、更新日2024-04-30。Webページではサトウキビや柑橘類なども掲載される一方、PDF施用量表では作物数がやや限定されるため、Webページを優先しつつ差分を要確認。', '高', true,
  NULL, NULL
FROM (SELECT u.id FROM users u JOIN maker_profiles mp ON mp.user_id = u.id WHERE u.role = 'maker' AND u.status = 'active' AND mp.company_name = 'ICL JAPAN' LIMIT 1) AS m
ON CONFLICT (name, maker_id) DO UPDATE SET
  product_type_id           = EXCLUDED.product_type_id,
  product_name_jp           = EXCLUDED.product_name_jp,
  general_purpose           = EXCLUDED.general_purpose,
  primary_compound          = EXCLUDED.primary_compound,
  mode_of_action            = EXCLUDED.mode_of_action,
  commercial_status         = EXCLUDED.commercial_status,
  technology_action         = EXCLUDED.technology_action,
  disease_pest_info         = EXCLUDED.disease_pest_info,
  expected_effects_official = EXCLUDED.expected_effects_official,
  expected_effects_farmille = EXCLUDED.expected_effects_farmille,
  usage_summary             = EXCLUDED.usage_summary,
  precautions               = EXCLUDED.precautions,
  storage_shelf_life        = EXCLUDED.storage_shelf_life,
  notes                     = EXCLUDED.notes,
  confidence                = EXCLUDED.confidence,
  is_public                 = EXCLUDED.is_public,
  fertilizer_registered     = EXCLUDED.fertilizer_registered,
  pesticide_registered      = EXCLUDED.pesticide_registered,
  updated_at                = now();

