SELECT
  m.id, COALESCE((SELECT id FROM product_types WHERE name = 'バイオスティミュラント' LIMIT 1), (SELECT id FROM product_types WHERE name = 'BS資材' LIMIT 1)), 'BIOZ Onyx Permanent',
  'オニキスパーマネント', '果樹などの永年作物や馬鈴薯において、開花後の稔実歩合向上、不稔実抑制、収量・品質向上を目的とする',
  'リン酸、ホウ素、モリブデン、その他超微量要素、海藻エキス（アスコフィルム・ノドサム）含有', '配合された海藻エキスと含有微量要素由来の3つの生理作用により、花芽分化促進、花芽保持、養分供給を通じて稔実歩合と収量・品質の向上をもたらす', '公式ページ掲載',
  '海藻エキスと含有微量要素由来の3つの生理作用により、休眠中の花芽分化を促進し、花の寿命を延ばして栄養状態を向上させ、より効率的な養分保持と果実・塊根の形成を支援する', '明記なし', 'オニキスパーマネントは開花後の稔実歩合の向上を促す葉面散布剤（バイオスティミュラント）です。対象作物は、果樹などの永年作物や馬鈴薯向けで、開花後の不稔実を抑制する製品となります。配合された海藻エキスと含有微量要素由来の3つの生理作用により、収量・品質の向上をもたらします。花芽分化促進 - 休眠中の花芽分化を促進。花芽保持 - 花の寿命を延ばし、栄養状態を向上。養分供給 - より効率的な養分の保持と果実・塊根の形成。',
  '花芽をつくりやすくする、花を長持ちさせる、果実や塊根の形成を助ける、稔実歩合を高める、収量・品質向上を助ける', '推奨施用量は希釈倍率基準ではなく単位面積あたりの投下量50ml/10aが基準。オニキスパーマネント希釈液単独または農薬資材との混合希釈液をブームスプレイヤー、スピードスプレイヤーにて葉面散布する。アミノ酸肥料BIOZムーンストーンとの併用を推奨。', 'オニキスパーマネント希釈液単独の葉面散布の場合、少量散布6L~/10aが可能で、展着剤の使用を推奨。農薬資材との混合希釈液を葉面散布する場合、希釈倍率は混用する農薬資材に合わせる。農薬等と初めてタンク内で混合する前にボトルテストを行い、適合性を確認。石灰硫黄合剤、銅剤との混用を避ける。新規の施用量、製品もしくは施用方法を実施する前に小規模な試験を推奨。',
  '製造年月日より5年', '公式PDFの製品特性では物理的性質は暗褐色粘稠懸濁液、用途は葉面散布、製品荷姿1L/本、原産国ブラジル、製品コード500966、更新日2024-07-31。WebページとPDFの施用量表はいずれも馬鈴薯・果樹類を対象とし、施用量50ml/10a。', '高', true,
  NULL, NULL
FROM (SELECT u.id FROM users u JOIN maker_profiles mp ON mp.user_id = u.id WHERE u.role = 'maker' AND u.status = 'active' AND mp.company_name = 'ICL JAPAN' LIMIT 1) AS m
ON CONFLICT (name, maker_id) DO UPDATE SET
  product_type_id           = EXCLUDED.product_type_id,
  product_name_jp           = EXCLUDED.product_name_jp,
  general_purpose           = EXCLUDED.general_purpose,
  primary_compound          = EXCLUDED.primary_compound,
  mode_of_action            = EXCLUDED.mode_of_action,
  commercial_status         = EXCLUDED.commercial_status,
