SELECT
  m.id, COALESCE((SELECT id FROM product_types WHERE name = 'バイオスティミュラント' LIMIT 1), (SELECT id FROM product_types WHERE name = 'BS資材' LIMIT 1)), 'BIOZ Sunstone',
  'サンストーン', 'イネ科作物向けの種子処理により、種子の活力発現、根の発達促進、ストレス耐性向上を目的とする',
  'カリウム、モリブデン、亜鉛、その他海藻エキス（アスコフィルム・ノドサム）含有', '種子処理によって種子の活力発現、根の発達促進、ストレス耐性の向上という3つの作用をもたらす', '公式ページ掲載',
  '種子処理により、発根後の生育促進及び生理活性を促し、初期生育の均等化、根の発達、ストレス耐性向上を支援する', '明記なし', 'サンストーンは、イネ科作物向けの種子処理剤（バイオスティミュラント）で、発根後の生育促進及び生理活性を促します。「種子の活力発現」、「根の発達促進」、「ストレス耐性の向上」という3つの作用をもたらし、高収量実現のスターターとして、期待できます。種子の活力発現を促し、作物の初期生育をより均等化。根の発達を促進。ストレス耐性の向上。',
  '発芽後の初期生育をそろえる、根張りを助ける、乾燥などのストレスに強くする、スタートダッシュを助ける', '基本は種子処理。種子1kgに対する必要量を計算し、流動する種子に噴霧して塗抹処理し、処理後に十分乾燥させる。水稲（乾田直播）は1ml/種子1kg、10倍希釈。小麦は1.5ml/種子1kg、5倍希釈。トウモロコシは10ml/10aで希釈倍率は問い合わせ。', '化学反応を起こすおそれがあるため薬剤とタンクミックスしない。微生物資材とはタンクミックス可能で、この場合は塩素を含まない水で希釈。塗抹剤の殺虫・殺菌剤と併用する場合は、塗抹前に十分混ぜる。塗抹後の種子は5～20℃で保管し、およそ3週間以内に播種。単独塗抹の場合は粉の吸水性を考慮し、5～10倍程度に水で希釈して塗抹することも可能。',
  '製造年月日より3年', '公式PDFの製品特性では物理的性質は暗褐色粘稠懸濁液、用途は種子処理、製品荷姿1L/本、原産国ブラジル、製品コード500964、更新日2024-02-08。公式PDFには「種子処理の代わりに、播種時の植溝内土壌散布も可能」として20ml/10a、希釈倍率200～250倍、散布水量4～5L/10aの記載あり。', '高', true,
  NULL, NULL
FROM (SELECT u.id FROM users u JOIN maker_profiles mp ON mp.user_id = u.id WHERE u.role = 'maker' AND u.status = 'active' AND mp.company_name = 'ICL JAPAN' LIMIT 1) AS m
ON CONFLICT (name, maker_id) DO UPDATE SET
  product_type_id           = EXCLUDED.product_type_id,
  product_name_jp           = EXCLUDED.product_name_jp,
  general_purpose           = EXCLUDED.general_purpose,
  primary_compound          = EXCLUDED.primary_compound,
  mode_of_action            = EXCLUDED.mode_of_action,
  commercial_status         = EXCLUDED.commercial_status,
  technology_action         = EXCLUDED.technology_action,
  disease_pest_info         = EXCLUDED.disease_pest_info,
  expected_effects_official = EXCLUDED.expected_effects_official,
  expected_effects_farmille = EXCLUDED.expected_effects_farmille,
  usage_summary             = EXCLUDED.usage_summary,
  precautions               = EXCLUDED.precautions,
  storage_shelf_life        = EXCLUDED.storage_shelf_life,
  notes                     = EXCLUDED.notes,
  confidence                = EXCLUDED.confidence,
  is_public                 = EXCLUDED.is_public,
  fertilizer_registered     = EXCLUDED.fertilizer_registered,
  pesticide_registered      = EXCLUDED.pesticide_registered,
  updated_at                = now();

