-- products row 11: BIOZ Topaz / maker=ICL JAPAN
INSERT INTO products (
  maker_id, product_type_id, name, product_name_jp, general_purpose,
  primary_compound, mode_of_action, commercial_status,
  technology_action, disease_pest_info, expected_effects_official,
  expected_effects_farmille, usage_summary, precautions,
  storage_shelf_life, notes, confidence, is_public,
  fertilizer_registered, pesticide_registered
)
SELECT
  m.id, COALESCE((SELECT id FROM product_types WHERE name = 'バイオスティミュラント' LIMIT 1), (SELECT id FROM product_types WHERE name = 'BS資材' LIMIT 1)), 'BIOZ Topaz',
  'トパーズ', '大豆などの豆類で根粒活性を高め、窒素固定を促進する種子処理',
  'カリウム、モリブデン、その他超微量要素、海藻エキス（アスコフィルム・ノドサム）含有', 'モリブデン及び超微量要素の作用により根粒の活性を高め、窒素固定を促進する。最適なpHにより根粒菌の着生を促進する。', '公式ページ掲載',
  'モリブデン及び超微量要素の作用により根粒の活性を高め、発芽過程から窒素の吸収効率を促進し、根粒菌の着生と窒素固定を支援する', '明記なし', 'トパーズは、大豆などの豆類向けの種子処理剤（バイオスティミュラント）で、モリブデン及び超微量要素の作用により、根粒の活性を高め、窒素固定を促進する資材です。根粒菌の接種資材との相性も良く、近年研究が進んでいる微量要素群の生理活性に着目し、マメ科作物の高い生産性を実現します。発芽過程からの窒素の吸収効率を促進。深根性：乾燥耐性と養分吸収に優れた効果。作業性が良く、種子に均一に展着。最適なpH：根粒菌の着生を促進。PDFでは、種子処理剤として使用することで発根量増大、根粒形成促進、ダイズ植物体の窒素固定を促進と記載。',
  '根粒をつきやすくする、窒素固定を助ける、発芽直後から窒素を使いやすくする、根張りを助ける、乾燥時の養分吸収を助ける、種子に均一に付きやすい', '推奨施用量は15ml/10a。大豆及び豆類に対して播種直前に種子処理・塗抹処理する。種子1kgあたりの必要量は15ml/10aを10a当たり播種量で除して算出する。', '塗抹用の殺虫・殺菌剤と併用する場合は塗抹前に十分に混ぜる。粉衣用の殺菌剤、根粒菌資材と併用する場合は塗抹乾燥後、粉剤を粉衣させる。塗抹後の種子は5～20℃で保管し、およそ3週間以内に播種。高温過湿・長期保管は発芽率の悪化を招く。単独塗抹の場合は問い合わせ。新しい組み合わせの種子処理剤を試す場合は混和テストを行う。',
  '製造年月日より3年', '公式PDFの製品特性では物理的性質は暗褐色粘稠懸濁液、用途は種子処理剤、製品荷姿1L/本、原産国ブラジル、製品コード500965、更新日2024-02-22。BIOZトパーズ＋BIOZネフライトでBNF効率を高める併用推奨あり。', '高', true,
  NULL, NULL
FROM (SELECT u.id FROM users u JOIN maker_profiles mp ON mp.user_id = u.id WHERE u.role = 'maker' AND u.status = 'active' AND mp.company_name = 'ICL JAPAN' LIMIT 1) AS m
