INSERT INTO products (
  maker_id, product_type_id, name, product_name_jp, general_purpose,
  primary_compound, mode_of_action, commercial_status,
  technology_action, disease_pest_info, expected_effects_official,
  expected_effects_farmille, usage_summary, precautions,
  storage_shelf_life, notes, confidence, is_public,
  fertilizer_registered, pesticide_registered
)
SELECT
  m.id, COALESCE((SELECT id FROM product_types WHERE name = '粒状資材' LIMIT 1), (SELECT id FROM product_types WHERE name = 'BS資材' LIMIT 1)), '鉄力あぐりB12',
  '鉄力あぐりB12', '栽培期間が長い果菜類や果樹などに2価鉄を供給し、葉色改善、根張り強化、生育促進を支援する',
  'FeO（酸化第一鉄）、有機物、公式PDFではFeO、有機酸', 'FeO由来の2価鉄供給により、葉色改善、根張り強化、花芽充実、生育改善を促す', '公式ページ掲載',
  '粒状の2価鉄供給材として培土混合、圃場施用、果樹・樹木の根本散布により吸収しやすい鉄分を供給し、葉緑素形成と光合成を支援する', '明記なし', '3～5mmの粒で撒きやすい。使い続けても土壌蓄積がない。肥料成分が無く、肥料設計を変えずに使える。根に当たっても害がでにくく、局所施肥ができる。葉色改善による光合成促進、根張り強化による活着促進・生育促進、代謝正常化による生育維持。',
  '葉色を良くする、光合成を助ける、根張りを強くする、活着を助ける、生育を維持する、果菜類・果樹など長期栽培の生育を支える', '培土等への混合、圃場への全面散布、条まき、イチゴの株元施用、元肥との施用、果樹の元肥・追肥時の根本散布に使用。公式ページでは培土1Lあたり1g、圃場へ1反あたり50kg～100kgまたは1m2あたり50～100g、果樹などは1m未満100～200g/本、1m以上200～300g/本を標準施用量として記載。公式PDFでは果樹・樹木の樹高別施用量を0.5m以下50g/本、0.5～1m100g/本、1m以上100～200g/本と記載。', '栽培法・作物により施用量は変わるため、状況に応じて調整する必要あり。',
  '明記なし', '公式ページでは成分をFeO（酸化第一鉄）、有機物、規格18kgと記載。公式PDFでは形状は粒状（3～5mm）、内容量18kg、成分FeO、有機酸、用途は栽培期間が長い作物（～6ヶ月）と記載。WebとPDFで果樹・樹木の標準施用量に差分あり。', '高', true,
  NULL, NULL
FROM (SELECT u.id FROM users u JOIN maker_profiles mp ON mp.user_id = u.id WHERE u.role = 'maker' AND u.status = 'active' AND mp.company_name = '愛知製鋼' LIMIT 1) AS m
ON CONFLICT (name, maker_id) DO UPDATE SET
  product_type_id           = EXCLUDED.product_type_id,
