-- products row 15: モーニングエース / maker=アグロ カネショウ
INSERT INTO products (
  maker_id, product_type_id, name, product_name_jp, general_purpose,
  primary_compound, mode_of_action, commercial_status,
  technology_action, disease_pest_info, expected_effects_official,
  expected_effects_farmille, usage_summary, precautions,
  storage_shelf_life, notes, confidence, is_public,
  fertilizer_registered, pesticide_registered
)
SELECT
  m.id, COALESCE((SELECT id FROM product_types WHERE name = '機能性液肥' LIMIT 1), (SELECT id FROM product_types WHERE name = 'BS資材' LIMIT 1)), 'モーニングエース',
  'モーニングエース', '果樹の着色促進、品質向上、糖度向上、日持ち向上を目的とする葉面散布用の機能性液肥',
  '保証成分量（％）：N2.0、P7.0、K1.0、B0.50、効果発現促進材：Ca0.31、その他成分：コリン、海藻抽出物、タウリン、窒素全量を含有する原料：りん酸コリン、タウリン、海藻抽出物', 'コリンは細胞膜を構成する成分の一つとして知られ、植物体内への浸透移行性に優れ、光合成の活性化や発根を促す作用があり、果実の肥大や着色、糖度などの品質向上が期待できる。海藻抽出物にはミネラル、アミノ酸、ビタミンなどが含まれ、糖度や日持ち向上、食味・食感の改善、環境ストレスで低下した樹勢の回復が期待できる', '公式ページ掲載',
  'コリン、海藻抽出物、アミノ酸をバランスよく配合し、光合成促進、細胞膜強化、糖度向上、果実着色向上、日持ち向上を支援する', '明記なし', 'コリンと海藻抽出物、アミノ酸をバランスよく配合した葉面散布肥料です。光合成を促進し、細胞膜も強化するため、糖度向上による果実の着色向上、また日持ち向上が期待できます。海藻抽出物とタウリンの働きで着色促進。コリンは光合成の活性化や発根を促す作用があり、果実の肥大や着色、糖度などの品質向上が期待できます。海藻抽出物は糖度や日持ち向上、食味・食感の改善など、作物品質の向上が期待されます。また、環境ストレスによって低下した樹勢の回復も期待できます。',
  '着色を助ける、糖度を上げる、日持ちを良くする、光合成を助ける、細胞膜を強くする、果実品質を高める、環境ストレス後の樹勢回復を助ける', '500～600倍に希釈して樹全体に散布する。作物・品種により使用時期が異なり、りんご早生・中生は収穫15～20日前、りんご晩生種・なし・かきは収穫30～40日前、おうとうは着色初期および収穫7日前、ももは収穫15～30日前、ぶどうはとび玉の入った頃に使用する。', '海藻由来の沈殿がみられることがあるが、品質上問題ない。眼に入らないように注意し、眼に入った場合は直ちに水でよく洗い流す。皮ふに付着した場合は、石けんでよく洗い落とす。小児の手の届く所には置かない。空容器は放置せず適切に処理。使用前にラベルをよく読む。',
  '有効年限は公式ページで「-」。保管は密栓し、直射日光をさけ、食品と区別して、冷涼な所。', '公式ページでは包装500g×20本、性状・有効年限・毒性・危険物は「-」表記。公式チラシではバイオスティミュラント資材の説明も掲載されている。モーニングはアグロ カネショウ株式会社の登録商標。', '高', true,
  NULL, NULL
FROM (SELECT u.id FROM users u JOIN maker_profiles mp ON mp.user_id = u.id WHERE u.role = 'maker' AND u.status = 'active' AND mp.company_name = 'アグロ カネショウ' LIMIT 1) AS m
ON CONFLICT (name, maker_id) DO UPDATE SET
  product_type_id           = EXCLUDED.product_type_id,
  product_name_jp           = EXCLUDED.product_name_jp,
  general_purpose           = EXCLUDED.general_purpose,
  primary_compound          = EXCLUDED.primary_compound,
  mode_of_action            = EXCLUDED.mode_of_action,
  commercial_status         = EXCLUDED.commercial_status,
  technology_action         = EXCLUDED.technology_action,
  disease_pest_info         = EXCLUDED.disease_pest_info,
  expected_effects_official = EXCLUDED.expected_effects_official,
  expected_effects_farmille = EXCLUDED.expected_effects_farmille,
  usage_summary             = EXCLUDED.usage_summary,
  precautions               = EXCLUDED.precautions,
  storage_shelf_life        = EXCLUDED.storage_shelf_life,
  notes                     = EXCLUDED.notes,
  confidence                = EXCLUDED.confidence,
  is_public                 = EXCLUDED.is_public,
  fertilizer_registered     = EXCLUDED.fertilizer_registered,
  pesticide_registered      = EXCLUDED.pesticide_registered,
